using UnityEngine;/// <summary>Meta del nivel: al tocarla el jugador termina el nivel y este vuelve a empezar.</summary>public class FinishPoint : MonoBehaviour{    [SerializeField] LayerMask characterLayer;    [SerializeField] float characterDetectionRange;    void Update()    {        var hit = Physics2D.OverlapCircle(transform.position, characterDetectionRange, characterLayer);        if (!hit || !hit.TryGetComponent<PlayerController>(out var player))            return;        player.Finish();        Destroy(gameObject);    }}